package br.gov.go.ppgo.espp.controller;import br.gov.go.ppgo.espp.domain.IdentidadeVisual;import br.gov.go.ppgo.espp.repository.IdentidadeVisualRepository;import br.gov.go.ppgo.espp.service.AuditoriaService;import java.io.IOException;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1") public class IdentidadeVisualController{private static final Set<String>K=Set.of("site-light","site-dark","admin-light","admin-dark","brasao-light","brasao-dark");private final IdentidadeVisualRepository r;private final AuditoriaService a;public IdentidadeVisualController(IdentidadeVisualRepository r,AuditoriaService a){this.r=r;this.a=a;}@GetMapping("/identidade-visual/{k}")public ResponseEntity<byte[]>imagem(@PathVariable String k){val(k);return r.findById(k).map(x->ResponseEntity.ok().cacheControl(CacheControl.noCache()).contentType(MediaType.parseMediaType(x.getContentType())).body(x.getConteudo())).orElseGet(()->ResponseEntity.notFound().build());}@PutMapping(value="/admin/configuracoes/identidade-visual/{k}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public void salvar(@PathVariable String k,@RequestPart("arquivo")MultipartFile f,Authentication auth)throws IOException{val(k);String t=f.getContentType();if(f.isEmpty()||f.getSize()>3_000_000)throw new IllegalArgumentException("A imagem deve ter no máximo 3 MB.");if(!Set.of("image/png","image/jpeg","image/webp","image/svg+xml").contains(t))throw new IllegalArgumentException("Use PNG, JPG, WebP ou SVG.");var x=r.findById(k).orElseGet(IdentidadeVisual::new);x.atualizar(k,f.getBytes(),t,ator(auth));r.save(x);a.registrar("CONFIGURACOES","EDICAO",k,"Identidade visual",ator(auth),null,Map.of("chave",k));}@DeleteMapping("/admin/configuracoes/identidade-visual/{k}")@ResponseStatus(HttpStatus.NO_CONTENT)public void remover(@PathVariable String k,Authentication auth){val(k);r.deleteById(k);a.registrar("CONFIGURACOES","EXCLUSAO",k,"Identidade visual",ator(auth),null,Map.of("chave",k));}private void val(String k){if(!K.contains(k))throw new IllegalArgumentException("Imagem inválida.");}private String ator(Authentication x){return x==null?"sistema":x.getName();}}
